package br.com.autofiscalia;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.text.*;
import java.util.*;
import java.net.*;
import org.json.*;

public class MainActivity extends Activity {
    private final int NAVY=Color.rgb(12,31,61), BLUE=Color.rgb(19,94,200), BG=Color.rgb(244,247,252);
    private LinearLayout root, content;
    private android.content.SharedPreferences prefs;
    private static final int PICK_FILE=71;
    private String company="";
    private static final String API_BASE="https://loja-com.com/autofiscal-api/";
    private String deviceId;
    @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("autofiscal",MODE_PRIVATE);company=prefs.getString("company","");deviceId=prefs.getString("device_id","");if(deviceId.isEmpty()){deviceId=UUID.randomUUID().toString();prefs.edit().putString("device_id",deviceId).apply();}showActivation();}
    private GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(radius);return d;}
    private TextView text(String value,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,Typeface.BOLD);t.setPadding(0,8,0,8);return t;}
    private void base(String title,String subtitle){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);setContentView(root);LinearLayout head=new LinearLayout(this);head.setOrientation(LinearLayout.VERTICAL);head.setPadding(24,28,24,22);head.setBackgroundColor(NAVY);head.addView(text(title,25,Color.WHITE,true));head.addView(text(subtitle,13,0xFFBFD3EF,false));root.addView(head);ScrollView scroll=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(22,22,22,32);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
    private void card(String title,String detail){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(18,16,18,16);c.setBackground(bg(Color.WHITE,18));c.addView(text(title,17,NAVY,true));c.addView(text(detail,14,0xFF52627A,false));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=14;content.addView(c,p);}
    private void button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(BLUE));b.setOnClickListener(v->action.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=10;content.addView(b,p);}
    private void note(String s){content.addView(text(s,13,0xFF64748B,false));}
    private void api(String endpoint, JSONObject data, java.util.function.Consumer<JSONObject> success){
        if(API_BASE.contains("SEU-DOMINIO")){new AlertDialog.Builder(this).setTitle("Configuração necessária").setMessage("Configure o endereço HTTPS do servidor em MainActivity.java antes de compilar.").setPositiveButton("OK",null).show();return;}
        new Thread(()->{try{
            URL u=new URL(API_BASE+endpoint);HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=utf-8");
            data.put("device_id",deviceId);try(OutputStream o=c.getOutputStream()){o.write(data.toString().getBytes("UTF-8"));}
            InputStream stream=c.getResponseCode()<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream buffer=new ByteArrayOutputStream();byte[] bytes=new byte[4096];int n;while((n=stream.read(bytes))!=-1)buffer.write(bytes,0,n);JSONObject response=new JSONObject(buffer.toString("UTF-8"));c.disconnect();runOnUiThread(()->{if(response.optBoolean("ok"))success.accept(response);else new AlertDialog.Builder(this).setTitle("Não foi possível concluir").setMessage(response.optString("error","Tente novamente.")).setPositiveButton("OK",null).show();});
        }catch(Exception e){runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Erro de conexão").setMessage("Confira a internet e o endereço do servidor. "+e.getMessage()).setPositiveButton("OK",null).show());}}).start();
    }
    private void checkLicense(){api("status.php",new JSONObject(),r->{if(r.optBoolean("active")){prefs.edit().putLong("expires",r.optLong("expires")).apply();showHome();}else{prefs.edit().remove("expires").apply();Toast.makeText(this,"Pagamento ainda não confirmado",Toast.LENGTH_LONG).show();}});}
    private void startPayment(){api("create.php",new JSONObject(),r->{String url=r.optString("url","");if(!url.startsWith("https://checkout.infinitepay.com.br/")){Toast.makeText(this,"Checkout inválido",Toast.LENGTH_LONG).show();return;}prefs.edit().putString("order",r.optString("order_nsu")).apply();startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));new AlertDialog.Builder(this).setTitle("Pagamento iniciado").setMessage("Pague via Pix no checkout da InfinitePay. Depois volte ao aplicativo e toque em Verificar pagamento.").setPositiveButton("Entendi",null).show();});}
    private void showActivation(){base("AutoFiscal IA","Ative seu acesso anual");card("Plano anual • R$ 9,90","Acesso por 365 dias ao organizador de documentos e relatórios locais.");card("Pix pela InfinitePay","O pagamento é feito no checkout seguro da InfinitePay. A liberação depende da confirmação oficial da transação.");button("Pagar R$ 9,90",()->startPayment());button("Verificar pagamento / Restaurar acesso",()->checkLicense());note("Recursos fiscais nesta versão: cálculos ilustrativos e relatórios locais. Não há transmissão de declarações à Receita Federal.");}
    @Override protected void onResume(){super.onResume();if(prefs!=null&&deviceId!=null&&prefs.getLong("expires",0)>System.currentTimeMillis()/1000){api("status.php",new JSONObject(),r->{if(!r.optBoolean("active")){prefs.edit().remove("expires").apply();showActivation();}});}}
    private void showHome(){if(prefs.getLong("expires",0)<=System.currentTimeMillis()/1000){showActivation();return;}base("Painel fiscal","Organização inteligente • Ambiente de testes");card("Empresa cadastrada",company.isEmpty()?"Nenhuma empresa cadastrada":company);card("Documentos importados",prefs.getInt("docs",0)+" arquivo(s) selecionado(s) neste dispositivo");button("Cadastrar empresa",()->showCompany());button("Importar documento",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/pdf","text/xml","application/xml","text/csv"});startActivityForResult(i,PICK_FILE);});button("Simular cálculo de tributos",()->showCalculator());button("Gerar relatório local",()->showReport());button("Voltar à ativação",()->showActivation());note("Os dados cadastrados permanecem neste dispositivo. Não há envio fiscal nem validação automática de CNPJ.");}
    private void showCompany(){base("Cadastrar empresa","Dados armazenados localmente");EditText name=new EditText(this);name.setHint("Razão social");name.setSingleLine(true);name.setText(company);content.addView(name);EditText cnpj=new EditText(this);cnpj.setHint("CNPJ (14 dígitos)");cnpj.setInputType(2);cnpj.setText(prefs.getString("cnpj",""));content.addView(cnpj);Spinner regime=new Spinner(this);String[] opts={"MEI","Simples Nacional","Lucro Presumido","Lucro Real"};regime.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,opts));content.addView(regime);button("Salvar empresa",()->{String digits=cnpj.getText().toString().replaceAll("\\D","");if(name.getText().toString().trim().isEmpty()||digits.length()!=14){Toast.makeText(this,"Informe a razão social e 14 dígitos do CNPJ",Toast.LENGTH_LONG).show();return;}company=name.getText().toString().trim();prefs.edit().putString("company",company).putString("cnpj",digits).putString("regime",opts[regime.getSelectedItemPosition()]).apply();showHome();});button("Voltar",()->showHome());}
    private void showCalculator(){base("Estimativa ilustrativa","Não substitui apuração tributária");note("Insira uma receita para calcular um exemplo didático com alíquota fixa de 6%. A alíquota NÃO representa necessariamente o imposto devido.");EditText revenue=new EditText(this);revenue.setHint("Receita em R$ (ex.: 12500,00)");revenue.setInputType(8194);content.addView(revenue);button("Calcular exemplo",()->{try{double value=Double.parseDouble(revenue.getText().toString().replace(".","").replace(",","."));if(value<0)throw new Exception();double tax=value*0.06;prefs.edit().putString("example",String.format(new Locale("pt","BR"),"Receita: R$ %.2f\nAlíquota hipotética: 6%%\nResultado ilustrativo: R$ %.2f",value,tax)).apply();new AlertDialog.Builder(this).setTitle("Resultado ilustrativo").setMessage(prefs.getString("example","")+"\n\nNão é uma guia, DARF ou declaração oficial.").setPositiveButton("OK",null).show();}catch(Exception e){Toast.makeText(this,"Informe um valor válido",Toast.LENGTH_SHORT).show();}});button("Voltar",()->showHome());}
    private void showReport(){base("Relatório local","Resumo para conferência");String report="AUTOFISCAL IA — RELATÓRIO DE TESTES\n\nEmpresa: "+(company.isEmpty()?"Não cadastrada":company)+"\nCNPJ: "+prefs.getString("cnpj","Não informado")+"\nRegime: "+prefs.getString("regime","Não informado")+"\nDocumentos selecionados: "+prefs.getInt("docs",0)+"\n\n"+prefs.getString("example","Nenhum cálculo realizado")+"\n\nDOCUMENTO ILUSTRATIVO. NÃO É DECLARAÇÃO, GUIA OU COMPROVANTE DA RECEITA FEDERAL.";content.addView(text(report,15,NAVY,false));button("Compartilhar relatório",()->{Intent send=new Intent(Intent.ACTION_SEND);send.setType("text/plain");send.putExtra(Intent.EXTRA_TEXT,report);startActivity(Intent.createChooser(send,"Compartilhar relatório"));});button("Voltar",()->showHome());}
    @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==PICK_FILE&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri uri=data.getData();String type=getContentResolver().getType(uri);if(type==null)type="";if(!(type.equals("application/pdf")||type.contains("xml")||type.equals("text/csv")||type.equals("application/octet-stream"))){Toast.makeText(this,"Tipo de arquivo não suportado",Toast.LENGTH_LONG).show();return;}prefs.edit().putInt("docs",prefs.getInt("docs",0)+1).apply();Toast.makeText(this,"Arquivo selecionado. Conteúdo ainda não processado.",Toast.LENGTH_LONG).show();showHome();}}
    @Override public void onBackPressed(){if(prefs.getLong("expires",0)>System.currentTimeMillis()/1000)showHome();else showActivation();}
}
